import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { MeshBasicNodeMaterial } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene positioning
  group.position.copy(config.scenePosition);
  if (config.sceneRotation) {
    group.rotation.order = 'XYZ';
    group.rotation.set(
      config.sceneRotation.x || 0,
      config.sceneRotation.y || 0,
      config.sceneRotation.z || 0
    );
  }
  if (config.sceneScale) {
    group.scale.copy(config.sceneScale);
  }

  // Load texture
  const tex = ctx.textureLoader.load(config.imageUrl);
  tex.colorSpace = THREE.SRGBColorSpace;

  // Apply atlas region if available
  if (config.atlasRegion && config.atlasSize) {
    const region = config.atlasRegion;
    const atlasSize = config.atlasSize;
    tex.offset.set(
      region.x / atlasSize.width,
      region.y / atlasSize.height
    );
    tex.repeat.set(
      region.width / atlasSize.width,
      region.height / atlasSize.height
    );
  }

  // Create plane with 512:320 aspect ratio
  const planeHeight = 0.5;
  const planeWidth = planeHeight * (512 / 320);
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Create material using TSL
  const material = new MeshBasicNodeMaterial();
  material.colorNode = texture(tex);

  // Create and add plane mesh
  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // Add text content
  if (config.textContent && config.textContent.length > 0) {
    const textConfig = config.textContent[0];
    const textMesh = ctx.fontAtlas.createText(textConfig.text, {
      fontSize: textConfig.fontSize || 0.39,
      fontWeight: textConfig.fontWeight || 400,
      fontFamily: 'Lora',
      color: config.colors.ink,
      align: 'center',
      baseline: 'middle'
    });
    textMesh.position.z = 0.01;
    group.add(textMesh);
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    tex.dispose();
  };

  // Setup event handlers
  group.userData.handlers = {};

  return group;
}
